sys_script_client.script:
function onSubmit() {
   //Type appropriate comment here, and begin script below
	var decision = g_form.getValue('decision');
	var decisionReason = g_form.getValue('decision_reason');
	var outcome = g_form.getValue('outcome');
	var actionName = g_form.getActionName();	
	var trade_task_type = g_form.getValue('trade_task_type');
	if(actionName == 'sysverb_insert_task' && decision == 'Reject and create a new task' && decisionReason == 'Other' && g_form.getValue('work_notes') == ''){
		g_form.setMandatory('work_notes',true);
		g_form.addErrorMessage('The following mandatory fields are not filled in: Comments');
		return false;
	}
	if(actionName == 'sysverb_insert_task' && (outcome == 'Leave the Sanctioned Trade Pending' || outcome =='Progress the Sanctioned Trade') && trade_task_type == 'Maker' && g_form.getValue('work_notes') == ''){
		g_form.setMandatory('work_notes',true);
		g_form.addErrorMessage('The following mandatory fields are not filled in: Comments');
		return false;
	}

}
